159	    /**
160	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 3, assigned at creation: it
161	     * starts at 1, gains 1 when an email is present, gains 1 when the owner's name was unique at
162	     * creation time ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
163	     */
164	    @Transient
165	    public Integer getMembershipLevel() {
166	        int level = 1;
167	        if (this.email != null && !this.email.isBlank()) {
168	            level++;
169	        }
170	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
171	            level++;
172	        }
173	        return Math.min(level, 3);
