46	@Service
47	public class ClinicServiceImpl implements ClinicService {
48	
49	    /** Dedicated audit channel; create side-effects are published here for auditing. */
50	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
51	
52	    /**
53	     * When more owners than this have already been created on a given day (by {@code
54	     * registrationDate}), a newly created owner is flagged with {@code bulkSignupWarning}.
