73	        this.vetRepository = vetRepository;
74	        this.ownerRepository = ownerRepository;
75	        this.visitRepository = visitRepository;
76	        this.specialtyRepository = specialtyRepository;
77	        this.petTypeRepository = petTypeRepository;
78	    }
79	
80	    @Override
