247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        boolean isNew = owner.isNew();
251	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
252	        // roll it forward to the next business day so it never lands on a weekend. Everything
253	        // derived from the registration date below must use this adjusted value.
254	        LocalDate registrationDate = toBusinessDay(
255	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
256	        owner.setRegistrationDate(registrationDate);
257	        if (owner.isNew() && ownerRepository.existsByTelephone(owner.getTelephone())) {
258	            throw new DuplicateTelephoneException(owner.getTelephone());
259	        }
260	        if (owner.isNew() && isEmailAlreadyUsed(owner)) {
261	            throw new DuplicateEmailException(owner.getEmail());
262	        }
263	        if (owner.isNew()
264	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
265	            throw new CityOwnerLimitExceededException(owner.getCity());
266	        }
267	        if (owner.isNew()
268	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
269	            throw new DailyOwnerLimitExceededException(registrationDate);
270	        }
271	        if (owner.isNew()) {
272	            List<Owner> householdMembers = findHouseholdMembers(owner);
273	            if (!householdMembers.isEmpty()) {
274	                if (!owner.isSharesHousehold()) {
275	                    throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
276	                }
277	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
278	            }
279	            // Size of the household after this create: the existing members plus this new owner.
280	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
281	        }
282	        if (owner.isNew() && owner.getCustomerCode() == null) {
283	            owner.setCustomerCode(generateCustomerCode(owner));
284	        }
285	        if (owner.isNew()) {
286	            owner.setNamesakeCount(countNamesakes(owner));
287	            owner.setBulkSignupWarning(
288	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
289	        }
290	        if (owner.getMembershipNumber() == null) {
291	            owner.setMembershipNumber(generateMembershipNumber(owner));
292	        }
293	        ownerRepository.save(owner);
294	        if (isNew) {
295	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
296	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
297	                owner.getRegistrationDate());
298	        }
299	    }
300	
301	    /**
302	     * Report whether {@code owner}'s email is already used by any existing owner, compared
303	     * case-insensitively on its lower-cased form. An owner without an email (null or blank) never
304	     * collides, so such an owner is reported as not using an already-taken email.
305	     */
306	    private boolean isEmailAlreadyUsed(Owner owner) {
307	        String email = owner.getEmail();
308	        if (email == null || email.isBlank()) {
309	            return false;
310	        }
311	        String normalized = email.toLowerCase();
312	        return ownerRepository.findAll().stream()
313	            .map(Owner::getEmail)
314	            .filter(existing -> existing != null)
315	            .anyMatch(existing -> normalized.equals(existing.toLowerCase()));
316	    }
317	
318	    /**
319	     * Count the owners that already exist (before this create) sharing the same first name and last
320	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
321	     * unique among the existing owners.
322	     */
323	    private int countNamesakes(Owner owner) {
324	        String firstName = owner.getFirstName();
325	        String lastName = owner.getLastName();
326	        if (firstName == null || lastName == null) {
327	            return 0;
328	        }
329	        return (int) ownerRepository.findAll().stream()
330	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
331	                && lastName.equalsIgnoreCase(existing.getLastName()))
332	            .count();
333	    }
334	
335	    /**
336	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
337	     * last name and the same address. Last names are compared case-insensitively with collapsed
338	     * whitespace; addresses are compared in their canonical normalized form (see
339	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
340	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
341	     * match on.
342	     */
343	    private List<Owner> findHouseholdMembers(Owner owner) {
344	        String lastName = normalizeHouseholdKey(owner.getLastName());
345	        String address = AddressNormalizer.normalize(owner.getAddress());
346	        if (lastName == null || address == null) {
347	            return List.of();
348	        }
349	        return ownerRepository.findAll().stream()
350	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
351	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
352	            .toList();
353	    }
354	
355	    /**
356	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
357	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
358	     * new one is generated. The resolved value is back-filled onto every member that is missing it
359	     * (or has a different one) so all members of the household share the same identifier.
360	     */
361	    private String resolveHouseholdId(List<Owner> members) {
362	        String householdId = members.stream()
363	            .map(Owner::getHouseholdId)
364	            .filter(id -> id != null && !id.isBlank())
365	            .findFirst()
366	            .orElseGet(() -> UUID.randomUUID().toString());
367	        for (Owner member : members) {
368	            if (!householdId.equals(member.getHouseholdId())) {
369	                member.setHouseholdId(householdId);
370	                ownerRepository.save(member);
371	            }
372	        }
373	        return householdId;
374	    }
375	
376	    /**
377	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
378	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
379	     */
380	    private String normalizeHouseholdKey(String value) {
381	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
382	    }
383	
384	    /**
385	     * Build an owner's {@code customerCode} as {@code '<CITY3>-<LAST3>-<NNNN>'}: CITY3 is the
386	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
387	     * letters of the owner's last name, and NNNN a per-city 4-digit zero-padded sequence equal
388	     * to one more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
389	     */
390	    private String generateCustomerCode(Owner owner) {
391	        String city3 = upperPrefix3(owner.getCity());
392	        String last3 = upperPrefix3(owner.getLastName());
393	        long sequence = countOwnersInCity(owner) + 1L;
394	        return String.format("%s-%s-%04d", city3, last3, sequence);
395	    }
396	
397	    /**
398	     * Return the upper-cased first three letters of {@code value} (or fewer when it is shorter),
399	     * the shared truncate-and-upper idiom used for each {@code customerCode} prefix segment.
400	     */
401	    private String upperPrefix3(String value) {
402	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
403	    }
404	
405	    /**
406	     * Count the owners that already exist (before this create) in the same city as {@code owner},
407	     * compared case-insensitively.
408	     */
409	    private long countOwnersInCity(Owner owner) {
410	        String city = owner.getCity();
411	        return ownerRepository.findAll().stream()
412	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
413	            .count();
414	    }
415	
416	    /**
417	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
418	     * on the given {@code date}. Used to enforce the per-day create cap.
419	     */
420	    private long countOwnersRegisteredOn(LocalDate date) {
421	        return ownerRepository.findAll().stream()
422	            .filter(existing -> date.equals(existing.getRegistrationDate()))
423	            .count();
424	    }
425	
426	    /**
427	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
428	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
429	     * are required to fall on a business day.
430	     */
431	    private LocalDate toBusinessDay(LocalDate date) {
432	        switch (date.getDayOfWeek()) {
433	            case SATURDAY:
434	                return date.plusDays(2);
435	            case SUNDAY:
436	                return date.plusDays(1);
437	            default:
438	                return date;
439	        }
440	    }
441	
442	    /**
443	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
444	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
445	     */
446	    private String generateMembershipNumber(Owner owner) {
447	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
448	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
449	    }
450	
451	    @Override
452	    @Transactional(readOnly = true)
453	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
454	        return ownerRepository.findByLastName(lastName);
455	    }
456	
457	    @Override
458	    @Transactional(readOnly = true)
459	    public Collection<Visit> findVisitsByPetId(int petId) {
460	        return visitRepository.findByPetId(petId);
461	    }
462	
463	    @Override
464	    @Transactional(readOnly = true)
465	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
466	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
467	    }
468	
469	    private <T> T findEntityById(Supplier<T> supplier) {
470	        try {
471	            return supplier.get();
472	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
473	            // Just ignore not found exceptions for Jdbc/Jpa realization
474	            return null;
475	        }
476	    }
477	
478	}
